import json
Q=[]
def q(n,ru,kk,ropts,kopts=None,**kw):
    d={'n':n,'ru':{'q':ru,'opts':ropts},'kk':{'q':kk,'opts':kopts if kopts is not None else ropts}}; d.update(kw); Q.append(d)
q(1,"Масса вишни 4,5 ц, а масса банана 250000 г. Найдите отношение массы вишни к массе банана.","Шиенің массасы 4,5 ц, ал банан массасы 250000 г. Шие массасының банан массасына қатынасын табыңыз.",[r"\(\tfrac95\)",r"\(\tfrac9{50}\)",r"\(\tfrac{50}9\)",r"\(\tfrac59\)"])
q(2,"Отец старше сына на 24 года. Если сейчас отцу 60 лет, то сколько лет назад отец был вдвое старше сына?","Әке ұлынан 24 жас үлкен. Қазір әкесі 60 жаста болса, әке ұлынан екі есе үлкен болғанына неше жыл болды?",["24","20","12","другой ответ"],["24","20","12","басқа жауап"])
q(3,"Расстояние между двумя городами 1600 км. Определите длину линии, соединяющей эти два города, на карте масштабом \\(1:200\\,000\\,000\\). Ответ дайте в миллиметрах.","Екі қала арасындағы қашықтық 1600 км. Масштабы \\(1:200\\,000\\,000\\) картада осы екі қаланы қосатын сызықтың ұзындығын анықтаңыз. Жауабын миллиметрмен беріңіз.",["0,08","0,8","8","80"])
q(4,"Опытному дрессировщику цирка для того, чтобы помыть слона, нужно 30 мин, а его сын справляется с этим заданием за 1,5 ч. Сколько времени им нужно, чтобы вместе помыть 2 слонов?","Цирктің тәжірибелі үйретушісіне пілді жуу үшін 30 минут қажет, ал оның ұлы бұл тапсырманы 1,5 сағатта орындайды. Екеуі бірге 2 пілді жуу үшін қанша уақыт қажет?",["30 мин","45 мин","60 мин","90 мин"])
q(5,"Две трети от одной трети числа равно восьми девятым. Что это за число?","Санның үштен бірінің үштен екісі тоғыздан сегізге тең. Бұл қандай сан?",["10","8","4","2"])
q(6,"Из города А в город Б выехали навстречу друг другу две машины. Первая машина до встречи проехала 240 км со скоростью 60 км/ч. Если скорость второй машины равна 110 км/ч, найдите путь второй машины.","А қаласынан Б қаласына екі көлік бір-біріне қарсы жолға шықты. Бірінші көлік кездескенге дейін 240 км жолды 60 км/сағ жылдамдықпен жүріп өтті. Екінші көліктің жылдамдығы 110 км/сағ болса, екінші көліктің жүрген жолын табыңыз.",["330","360","440","480"])
q(7,r"Вычислите: \(-1{,}1-(7{,}6-3{,}7)-(3{,}7-5{,}6)+0{,}2\)",r"Есептеңіз: \(-1{,}1-(7{,}6-3{,}7)-(3{,}7-5{,}6)+0{,}2\)",[r"\(-2{,}9\)",r"\(-1{,}9\)",r"\(-2{,}3\)",r"\(-1\)"])
q(8,"За 6 месяцев работы завод выполнил 60% объёма годового плана. Насколько % завод перевыполнит план, если будет работать в таком же темпе?","Зауыт 6 ай жұмыс істегенде жылдық жоспар көлемінің 60%-ын орындады. Осы қарқынмен жұмыс істесе, зауыт жоспарды неше пайызға асыра орындайды?",["10","20","50","75"])
q(9,"Если сумма 2021 положительных целых чисел равна 2022, то чему равно их произведение?","2021 оң бүтін санның қосындысы 2022-ге тең болса, олардың көбейтіндісі неге тең?",["1","2","2021","другой ответ"],["1","2","2021","басқа жауап"])
q(10,r"На починку колёс и двигателя мотоцикла было потрачено 240 деталей, что составляет \(\tfrac45\) всех деталей, истраченных на починку. А на ремонт было истрачено \(\tfrac45\) всех купленных деталей. Сколько деталей было куплено?",r"Мотоциклдің дөңгелектері мен қозғалтқышын жөндеуге 240 бөлшек жұмсалды, бұл жөндеуге жұмсалған барлық бөлшектердің \(\tfrac45\) бөлігін құрайды. Ал жөндеуге сатып алынған барлық бөлшектердің \(\tfrac45\) бөлігі жұмсалды. Барлығы қанша бөлшек сатып алынған?",["300","350","375","250"])
q(11,"На диаграмме показан уровень топлива в баке машины. Какое число соответствует уровню топлива в данный момент?","Диаграммада көліктің багындағы жанармай деңгейі көрсетілген. Қазіргі сәтте жанармай деңгейіне қандай сан сәйкес келеді?",["20","21","22","23"],figMid=['a3_gauge_@'])
q(12,"Когда цену компьютера снизили два раза на один и тот же процент, его цена упала с 80000 тенге до 51200 тенге. На сколько процентов снижалась цена в оба раза?","Компьютердің бағасын екі рет бірдей пайызға төмендеткенде, оның бағасы 80000 теңгеден 51200 теңгеге дейін түсті. Баға екі жолы да неше пайызға төмендеді?",["10","20","30","другой ответ"],["10","20","30","басқа жауап"])
q(13,r"Найдите сумму корней уравнения: \(\dfrac{|3x+1{,}5|}{-1{,}5}=\dfrac{3{,}2}{-9{,}6}\)",r"Теңдеудің түбірлерінің қосындысын табыңыз: \(\dfrac{|3x+1{,}5|}{-1{,}5}=\dfrac{3{,}2}{-9{,}6}\)",["0",r"\(\tfrac13\)","-1","-3"])
q(14,r"Какова должна быть скорость катера, чтобы проехать 60 м за \(\tfrac1{20}\) часа?",r"Катердің 60 м жолды \(\tfrac1{20}\) сағатта жүріп өтуі үшін оның жылдамдығы қандай болуы керек?",[r"\(\tfrac1{180}\) м/с",r"60 м/мин",r"\(\tfrac{0{,}6}{20}\) км/с",r"20 м/мин"],[r"\(\tfrac1{180}\) м/с",r"60 м/мин",r"\(\tfrac{0{,}6}{20}\) км/с",r"20 м/мин"])
q(15,r"Вычислите: \(\dfrac{3}{1+\dfrac{1}{1+\frac12}}\)",r"Есептеңіз: \(\dfrac{3}{1+\dfrac{1}{1+\frac12}}\)",["1,4",r"\(\tfrac78\)",r"\(\tfrac56\)",r"\(\tfrac95\)"])
q(16,"За месяц на заводе выпустили 240 тысяч смартфонов. 15% изготовленных смартфонов смогли пройти контроль качества. Сколько телефонов не прошло контроль качества?","Зауытта бір айда 240 мың смартфон шығарылды. Дайындалған смартфондардың 15%-ы сапа бақылауынан өте алды. Қанша телефон сапа бақылауынан өтпеді?",["36000","204000","204","36"])
q(17,r"Определите последнее действие: \(\big((-8-(8\cdot 8)-8\cdot(8:8-8)-8)\cdot(-10+10\cdot(-10))-(-8-(8:8)-8)\big)\cdot 8\)",r"Соңғы әрекетті анықтаңыз: \(\big((-8-(8\cdot 8)-8\cdot(8:8-8)-8)\cdot(-10+10\cdot(-10))-(-8-(8:8)-8)\big)\cdot 8\)",["Вычитание","Деление","Сложение","Умножение"],["Азайту","Бөлу","Қосу","Көбейту"])
q(18,"На карте масштабом 1:50 изображена линия длиной в 8 дм. Найдите это расстояние на местности. Ответ дайте в метрах.","Масштабы 1:50 картада ұзындығы 8 дм сызық бейнеленген. Осы қашықтықты жер бетінде табыңыз. Жауабын метрмен беріңіз.",["4","40","400","4000"])
